    $BIN run ../../compiler/stage1/data_asm_cc.lume ../../compiler/stage1/sh_oom.src "$ntmp/sh_oom.s" >/dev/null 2>&1; $BIN asm "$ntmp/sh_oom.s" "$ntmp/sh_oom" >/dev/null 2>&1
