    $BIN asm "$ntmp/bp_c.s" "$ntmp/bp_c_o.elf" >/dev/null 2>&1
    if ! ( [ -s "$ntmp/bp_c_o.elf" ] && cmp -s "$ntmp/bp_c_l.elf" "$ntmp/bp_c_o.elf" ); then bp=0; echo "  byte-perfect mismatch: whole compiler"; fi
    if [ "$bp" = 1 ]; then ok "self-host asm: lasm ELF == lume0 asm oracle byte-for-byte (nfib, bigints, whole compiler; 0 diff)"; else bad "self-host asm: lasm ELF == lume0 asm oracle byte-for-byte (0 diff)"; fi
    # top-level expression statements (ExprS in lumec / DExprS in the data_asmgen oracle): a program of
    # bare `emit(...)`/`flush()` statements (each value discarded, no `print`) must compile via BOTH lumec
    # and the oracle and print "Hi!" -- proving the statements run for effect and are never dropped.
    te_exp=../../tests/conformance/stage1/toplevel_expr_asm.expected
    "$ntmp/lc" <../../compiler/stage1/toplevel_expr.src >"$ntmp/te_l.s" 2>/dev/null; "$ntmp/lasm" <"$ntmp/te_l.s" >"$ntmp/te_l.elf" 2>/dev/null; chmod +x "$ntmp/te_l.elf"
    $BIN run ../../compiler/stage1/data_asm_cc.lume ../../compiler/stage1/toplevel_expr.src "$ntmp/te_o.s" >/dev/null 2>&1; $BIN asm "$ntmp/te_o.s" "$ntmp/te_o.elf" >/dev/null 2>&1; chmod +x "$ntmp/te_o.elf"
    if [ -x "$ntmp/te_l.elf" ] && "$ntmp/te_l.elf" 2>/dev/null | diff -u "$te_exp" - >/dev/null && [ -x "$ntmp/te_o.elf" ] && "$ntmp/te_o.elf" 2>/dev/null | diff -u "$te_exp" - >/dev/null; then ok "top-level expression statement (emit/flush, value discarded): lumec and data_asmgen oracle both -> native 'Hi!'"; else bad "top-level expression statement (emit/flush): lumec and oracle -> native"; fi
    # movabs boundaries: imm32 edges stay C7, anything outside becomes movabs; negatives and r8+ destinations must match the oracle byte for byte (whole file now; lasm appends no trailing newline).
    printf '.section .text\n.globl _start\n_start:\n    movq $-2147483649, %%rax\n    movq $2147483648, %%rcx\n    movq $-9223372036854775808, %%r8\n    movq $9223372036854775807, %%r15\n    movq $-4294967296, %%rdx\n    movq $-4294967297, %%rbx\n    movq $-2147483648, %%rsi\n    movq $2147483647, %%rdi\n    movq $4294967295, %%r9\n    movq $-1234567890123456789, %%r11\n    movq $60, %%rax\n    movq $0, %%rdi\n    syscall\n' >"$ntmp/mvabs.s"
    if "$ntmp/lasm" <"$ntmp/mvabs.s" >"$ntmp/mvabs_l.elf" 2>/dev/null && $BIN asm "$ntmp/mvabs.s" "$ntmp/mvabs_o.elf" >/dev/null 2>&1 && [ -s "$ntmp/mvabs_o.elf" ] && cmp -s "$ntmp/mvabs_l.elf" "$ntmp/mvabs_o.elf"; then ok "self-host asm: lasm movabs boundaries/negatives match the oracle byte for byte"; else bad "self-host asm: lasm movabs boundaries/negatives match the oracle byte for byte"; fi
    # GAS local numeric labels: a hand-written .s REUSES `1:` and uses `1f`/`1b`; each reference must resolve to the NEAREST definition (forward / backward). lasm must run it and print "ok"; the one-name-per-number oracle (elf.c) cannot, so its ELF must NOT print "ok" (timeout guards a hang) -- lasm is strictly stronger than the oracle here.
    ll_exp=../../tests/conformance/stage1/local_labels_asm.expected
    "$ntmp/lasm" <../../compiler/stage1/local_labels.s >"$ntmp/ll_l.elf" 2>/dev/null; chmod +x "$ntmp/ll_l.elf"
    $BIN asm ../../compiler/stage1/local_labels.s "$ntmp/ll_o.elf" >/dev/null 2>&1; chmod +x "$ntmp/ll_o.elf"
    if [ -s "$ntmp/ll_l.elf" ] && timeout 10 "$ntmp/ll_l.elf" 2>/dev/null | diff -u "$ll_exp" - >/dev/null && ! { [ -x "$ntmp/ll_o.elf" ] && timeout 5 "$ntmp/ll_o.elf" 2>/dev/null | diff -u "$ll_exp" - >/dev/null; }; then ok "self-host asm: lasm resolves GAS local numeric labels (1f/1b) by nearest, reused numbers OK"; else bad "self-host asm: lasm resolves GAS local numeric labels (1f/1b) by nearest, reused numbers OK"; fi
    # zero-C loop: after the one-time bootstrap (lasm built via lume0 asm above), the whole pipeline needs NO lume0 asm.
    # lumec compiles its own source to gen.s; LASM (not lume0 asm) assembles gen.s into a working lumecB ELF; lumecB
    # recompiles its own source to gen2.s and must reproduce gen.s bit-for-bit (fixpoint via lasm), and lumecB must
    # still compile nfib correctly (assembled by lasm). The buffered `emit`/`flush` makes assembling the ~300KB
    # compiler fast enough to run here (per-byte write(1) made this > 2 minutes).
    if "$ntmp/lc" <../../compiler/stage1/lumec.src >"$ntmp/z_gen.s" 2>/dev/null && "$ntmp/lasm" <"$ntmp/z_gen.s" >"$ntmp/z_lumecB.elf" 2>/dev/null && chmod +x "$ntmp/z_lumecB.elf" && "$ntmp/z_lumecB.elf" <../../compiler/stage1/lumec.src >"$ntmp/z_gen2.s" 2>/dev/null && [ -s "$ntmp/z_gen.s" ] && cmp -s "$ntmp/z_gen.s" "$ntmp/z_gen2.s" && "$ntmp/z_lumecB.elf" <../../compiler/stage1/nfib.src >"$ntmp/z_nfib.s" 2>/dev/null && "$ntmp/lasm" <"$ntmp/z_nfib.s" >"$ntmp/z_nfib.elf" 2>/dev/null && chmod +x "$ntmp/z_nfib.elf" && "$ntmp/z_nfib.elf" 2>/dev/null | diff -u ../../tests/conformance/stage1/nfib_asm.expected - >/dev/null; then ok "self-host zero-C loop: lumec|lasm assembles the compiler, result reproduces"; else bad "self-host zero-C loop: lumec|lasm assembles the compiler, result reproduces"; fi
    # phase-2 comptime: lumec folds comptime(expr) to a constant at COMPILE TIME (native, no C). Build ct.src
    # with the native lumec + native lasm, run it and assert the output; then grep the emitted .s to PROVE the
    # fold (each result is a `movq $N` immediate / a .rodata string, never a runtime add/imul).
    "$ntmp/lc" <../../compiler/stage1/ct.src >"$ntmp/ct.s" 2>/dev/null; "$ntmp/lasm" <"$ntmp/ct.s" >"$ntmp/ct.elf" 2>/dev/null; chmod +x "$ntmp/ct.elf"
    ct_ok=1
    "$ntmp/ct.elf" 2>/dev/null | diff -u ../../tests/conformance/stage1/comptime_asm.expected - >/dev/null || ct_ok=0
    # PROOF of compile-time folding: `fn main_val() = comptime(2 + 3 * 4)` must compile to a single `movq $14`
    # immediate with NO runtime arithmetic in its body (the runtime routines, which legitimately use addq/imulq,
    # live elsewhere -- so scope the check to main_val's body only).
    awk '/^main_val:/{p=1} p{print} p&&/^    ret$/{exit}' "$ntmp/ct.s" >"$ntmp/ct_mv.s"
    grep -q 'movq \$14, %rdi' "$ntmp/ct_mv.s" || ct_ok=0
    grep -Eq 'addq|imulq|subq|idivq' "$ntmp/ct_mv.s" && ct_ok=0
    if [ "$ct_ok" = 1 ]; then ok "phase-2 comptime: lumec folds comptime(expr) to a constant (native, no C)"; else bad "phase-2 comptime: lumec folds comptime(expr) to a constant (native, no C)"; fi
    # a comptime over something NOT constant-foldable (here a function call) is a HARD compile-time error:
    # lumec exits nonzero, writes a clear message to stderr, and emits no asm -- never a silently-wrong program.
    printf 'print comptime(f(1))\n' >"$ntmp/ctbad.src"
    "$ntmp/lc" <"$ntmp/ctbad.src" >"$ntmp/ctbad.s" 2>"$ntmp/ctbad.err"; ctbad_code=$?
    if [ "$ctbad_code" != 0 ] && [ ! -s "$ntmp/ctbad.s" ] && grep -q "comptime error" "$ntmp/ctbad.err"; then ok "phase-2 comptime: non-constant comptime fails compilation with a clear error (no bad output)"; else bad "phase-2 comptime: non-constant comptime fails compilation with a clear error"; fi
    # phase-2 C2: comptime EVALUATES calls to PURE user functions (recursion + if + arithmetic). ct2.src defines
    # fib/fact and prints comptime(fib(10))=55, comptime(fact(5))=120, a nested comptime, and comptime(fact(fib(5)))=120.
    "$ntmp/lc" <../../compiler/stage1/ct2.src >"$ntmp/ct2.s" 2>/dev/null; "$ntmp/lasm" <"$ntmp/ct2.s" >"$ntmp/ct2.elf" 2>/dev/null; chmod +x "$ntmp/ct2.elf"
    ct2_ok=1
    "$ntmp/ct2.elf" 2>/dev/null | diff -u ../../tests/conformance/stage1/comptime2_asm.expected - >/dev/null || ct2_ok=0
    # PROOF of compile-time folding: each comptime call becomes a `movq $N` immediate in the program-entry (main)
    # section -- there is NO `call fib`/`call fact` after `_start:` (fib/fact are still emitted as callable fns).
    awk '/^_start:/{p=1} p{print}' "$ntmp/ct2.s" >"$ntmp/ct2_main.s"
    grep -q 'movq \$55, %rdi' "$ntmp/ct2_main.s" || ct2_ok=0
    grep -q 'movq \$120, %rdi' "$ntmp/ct2_main.s" || ct2_ok=0
    grep -q 'call fib' "$ntmp/ct2_main.s" && ct2_ok=0
    grep -q 'call fact' "$ntmp/ct2_main.s" && ct2_ok=0
    if [ "$ct2_ok" = 1 ]; then ok "phase-2 C2: comptime folds pure user-fn calls fib(10)=55 / fact(5)=120 (no call in main)"; else bad "phase-2 C2: comptime folds pure user-fn calls"; fi
    # C2 purity guard: a comptime that reaches an impure builtin (read) is a hard compile-time error ('not pure').
    printf 'fn getx() = read()\nprint comptime(getx())\n' >"$ntmp/ctimp.src"
    "$ntmp/lc" <"$ntmp/ctimp.src" >"$ntmp/ctimp.s" 2>"$ntmp/ctimp.err"; ctimp_code=$?
    if [ "$ctimp_code" != 0 ] && [ ! -s "$ntmp/ctimp.s" ] && grep -q "not pure" "$ntmp/ctimp.err"; then ok "phase-2 C2: comptime of an impure fn (read) fails with 'not pure'"; else bad "phase-2 C2: comptime of an impure fn fails with 'not pure'"; fi
    # C2 termination guard (SUPERIOR to C++ constexpr): infinite comptime recursion hits a finite, explicit step/
