    if diff -u ../../tests/conformance/stage1/lfmt_asm.expected "$ntmp/fmt1.src" >/dev/null && cmp -s "$ntmp/fmt1.src" "$ntmp/fmt2.src" && LUME_BIN_DIR="$ntmp" ../../lume fmt --check ../../compiler/stage1/lfmt.src >/dev/null 2>&1 && cmp -s "$ntmp/fs_orig.s" "$ntmp/fs_fmt.s"; then ok "phase-2 T2: native lfmt.src canonical AST formatter (idempotent, self-canonical & codegen-invariant)"; else bad "phase-2 T2: native lfmt.src canonical AST formatter"; fi
    # phase-2 T3: modules (`use <mod>` topological bundler in Lume-Core `compiler/stage1/lmod.src`) + package manager (`lume pkg`: lume.toml, SHA-256 lume.lock, P26 capability audit).
    if LUME_BIN_DIR="$ntmp" ../../lume run ../../compiler/stage1/mod_app.src 2>/dev/null | diff -u ../../tests/conformance/stage1/lmod_app_asm.expected - >/dev/null; then ok "phase-2 T3: native lmod.src resolves diamond 'use' module graph and runs natively"; else bad "phase-2 T3: native lmod.src resolves diamond 'use' module graph"; fi
    mkdir -p "$ntmp/merr"
    printf 'use cyc_b\nfn fa(x) = x\nprint fa(1)\n' >"$ntmp/merr/cyc_a.src"
    printf 'use cyc_a\nfn fb(x) = x\n' >"$ntmp/merr/cyc_b.src"
    printf 'use no_such_mod\nprint 1\n' >"$ntmp/merr/miss.src"
    LUME_BIN_DIR="$ntmp" ../../lume build "$ntmp/merr/cyc_a.src" -o "$ntmp/merr/cyc.elf" 2>"$ntmp/merr/cyc.err"; cyc_rc=$?
    LUME_BIN_DIR="$ntmp" ../../lume build "$ntmp/merr/miss.src" -o "$ntmp/merr/miss.elf" 2>"$ntmp/merr/miss.err"; miss_rc=$?
    if [ "$cyc_rc" != 0 ] && grep -q "circular module dependency" "$ntmp/merr/cyc.err" && [ "$miss_rc" != 0 ] && grep -q "module 'no_such_mod' not found" "$ntmp/merr/miss.err"; then ok "phase-2 T3: native lmod.src rejects circular 'use' chains and missing modules"; else bad "phase-2 T3: native lmod.src cycle & missing-module errors"; fi
    LUME_BIN_DIR="$ntmp" ../../lume pkg init "$ntmp/pkgdemo" >/dev/null 2>&1
    LUME_BIN_DIR="$ntmp" ../../lume pkg lock "$ntmp/pkgdemo" >/dev/null 2>&1
    pkg_ok=1
    LUME_BIN_DIR="$ntmp" ../../lume pkg verify "$ntmp/pkgdemo" >/dev/null 2>&1 || pkg_ok=0
    printf '\n## tampered\n' >>"$ntmp/pkgdemo/main.src"
    LUME_BIN_DIR="$ntmp" ../../lume pkg verify "$ntmp/pkgdemo" >/dev/null 2>&1 && pkg_ok=0
    sed -i 's/allow = \["io"\]/allow = ["pure"]/' "$ntmp/pkgdemo/lume.toml"
    printf 'fn steal() = read()\n' >"$ntmp/pkgdemo/sneaky.src"
    printf 'use sneaky\nprint steal()\n' >"$ntmp/pkgdemo/main.src"
    LUME_BIN_DIR="$ntmp" ../../lume build "$ntmp/pkgdemo/main.src" -o "$ntmp/pkgdemo/main.elf" 2>"$ntmp/pkgdemo/cap.err" && pkg_ok=0
    grep -q "capability error: module 'sneaky' uses I/O capability 'read' not granted by lume.toml" "$ntmp/pkgdemo/cap.err" || pkg_ok=0
    if [ "$pkg_ok" = 1 ]; then ok "phase-2 T3: lume pkg (lume.toml, SHA-256 lume.lock drift detection & P26 capability audit)"; else bad "phase-2 T3: lume pkg lockfile & capability audit"; fi
    # phase-2 C3: generic functions via comptime type parameters (`fn id(comptime T: type, x: T)`). The comptime
    # parameter is ERASED at runtime (the function takes only the runtime params; each call drops the type arg),
    # the type parameter is bound at the call site and the remaining annotated args are checked (reusing F2).
    # POSITIVE: generics_ok.src defines id / pair_fst / pair_snd and prints id(int,42)=42, id(str,"hi")=hi, and a
    # two-type-parameter pair -> compiles via lumec -> lasm -> native and prints the expected values.
    "$ntmp/lc" <../../compiler/stage1/generics_ok.src >"$ntmp/go.s" 2>/dev/null; "$ntmp/lasm" <"$ntmp/go.s" >"$ntmp/go.elf" 2>/dev/null; chmod +x "$ntmp/go.elf"
    if [ -x "$ntmp/go.elf" ] && "$ntmp/go.elf" 2>/dev/null | diff -u ../../tests/conformance/stage1/generics_ok_asm.expected - >/dev/null; then ok "phase-2 C3: generic fns (comptime T: type) compile + run (native, no C)"; else bad "phase-2 C3: generic fns (comptime T: type) compile + run (native, no C)"; fi
    # PROOF of type erasure: for a one-runtime-param generic, `id(int, 42)` must emit a call to `id` passing ONLY the
    # runtime argument 42 -- the type argument is gone. In the program entry (main) the call site therefore loads the
    # literal 42 and calls `id` with a single register argument: `movq $42` and `call id` are present, and there is NO
    # `popq %rsi` (which a surviving second argument would have produced).
    printf 'fn id(comptime T: type, x: T) = x\nprint id(int, 42)\n' >"$ntmp/c3e.src"
    "$ntmp/lc" <"$ntmp/c3e.src" >"$ntmp/c3e.s" 2>/dev/null
    awk '/^_start:/{p=1} p{print}' "$ntmp/c3e.s" >"$ntmp/c3e_main.s"
    c3e_ok=1
    grep -q 'call id' "$ntmp/c3e_main.s" || c3e_ok=0
    grep -q 'movq \$42, %rdi' "$ntmp/c3e_main.s" || c3e_ok=0
    grep -q 'popq %rsi' "$ntmp/c3e_main.s" && c3e_ok=0
    if [ "$c3e_ok" = 1 ]; then ok "phase-2 C3: type erasure -- id(int, 42) calls id with ONE arg (type arg erased, no popq %rsi)"; else bad "phase-2 C3: type erasure -- id(int, 42) calls id with ONE arg"; fi
    # NEGATIVE: once the type parameter is bound (T := int), an argument of the wrong concrete type is a clear error.
    printf 'fn id(comptime T: type, x: T) = x\nprint id(int, "hi")\n' >"$ntmp/c3n.src"
    "$ntmp/lc" <"$ntmp/c3n.src" >"$ntmp/c3n.s" 2>"$ntmp/c3n.err"; c3n=$?
    if [ "$c3n" = 3 ] && [ ! -s "$ntmp/c3n.s" ] && grep -q "argument 2 of 'id' has type str but parameter 'x' expects int" "$ntmp/c3n.err"; then ok "phase-2 C3: wrong-typed argument after binding T is a clear type error (exit 3, no asm)"; else bad "phase-2 C3: wrong-typed argument after binding T is a clear type error"; fi
    # BACKWARD-COMPAT: programs that use no comptime parameter compile byte-identically through the C3 compiler.
    for prog in annot_ok types_ok ev nfib; do
        "$ntmp/lc" <../../compiler/stage1/$prog.src >"$ntmp/c3_$prog.s" 2>/dev/null; "$ntmp/lasm" <"$ntmp/c3_$prog.s" >"$ntmp/c3_$prog.elf" 2>/dev/null; chmod +x "$ntmp/c3_$prog.elf"
        if [ -x "$ntmp/c3_$prog.elf" ] && "$ntmp/c3_$prog.elf" 2>/dev/null | diff -u ../../tests/conformance/stage1/${prog}_asm.expected - >/dev/null; then ok "phase-2 C3: backward-compat -- comptime-free $prog.src unchanged"; else bad "phase-2 C3: backward-compat -- comptime-free $prog.src unchanged"; fi
    done
    # D2 generic row types: `table[T]` survives generic return substitution and rejects a mismatched row type.
    "$ntmp/lc" <../../compiler/stage1/table_generic.src >"$ntmp/tg.s" 2>"$ntmp/tg.err"
    "$ntmp/lasm" <"$ntmp/tg.s" >"$ntmp/tg.elf" 2>/dev/null; chmod +x "$ntmp/tg.elf"
    if [ -x "$ntmp/tg.elf" ] && "$ntmp/tg.elf" 2>/dev/null | diff -u ../../tests/conformance/stage1/table_generic_asm.expected - >/dev/null; then ok "phase-2 D2: table[T] annotations type-check generic function results"; else bad "phase-2 D2: table[T] annotations type-check generic function results"; cat "$ntmp/tg.err"; fi
    "$ntmp/lc" <../../compiler/stage1/table_generic_bad.src >"$ntmp/tgbad.s" 2>"$ntmp/tgbad.err"; tgbad=$?
    if [ "$tgbad" = 3 ] && [ ! -s "$ntmp/tgbad.s" ] && grep -q "has type table\[str\] but parameter 'table' expects table\[int\]" "$ntmp/tgbad.err"; then ok "phase-2 D2: table[T] rejects a mismatched generic row type"; else bad "phase-2 D2: table[T] rejects a mismatched generic row type"; fi
    printf 'type Customer = record id: int, spend: int, city: str\ntype Order = record id: int, customer_id: int\ntype Joined = record orders_id: int, orders_customer_id: int, customers_id: int, customers_spend: int, customers_city: str\ntype Agg = record city: str, count: int, sum: int\nfn q(table: table[Customer]) = query_where(Customer, table, "spend", ">", 4)\nfn o(table: table[Customer]) = query_order(Customer, table, "spend", "desc")\nfn j(a: table[Order], b: table[Customer]) = query_join(Order, Customer, Joined, a, b, "orders", "customers", "customer_id", "id")\nfn g(table: table[Customer]) = query_group(Customer, Agg, table, "city", "spend")\n' >"$ntmp/d3ok.src"
    "$ntmp/lc" <"$ntmp/d3ok.src" >"$ntmp/d3ok.s" 2>"$ntmp/d3ok.err"; d3ok=$?
    if [ "$d3ok" = 0 ] && [ -s "$ntmp/d3ok.s" ]; then ok "phase-2 D3: query field and literal types are accepted"; else bad "phase-2 D3: query field and literal types are accepted"; cat "$ntmp/d3ok.err"; fi
    printf 'type Customer = record id: int, spend: int\nfn q(table: table[Customer]) = query_where(Customer, table, "missing", ">", 4)\n' >"$ntmp/d3field.src"
    "$ntmp/lc" <"$ntmp/d3field.src" >"$ntmp/d3field.s" 2>"$ntmp/d3field.err"; d3field=$?
    if [ "$d3field" = 3 ] && [ ! -s "$ntmp/d3field.s" ] && grep -q "query on 'Customer' has no field 'missing'" "$ntmp/d3field.err"; then ok "phase-2 D3: query rejects an unknown record field"; else bad "phase-2 D3: query rejects an unknown record field"; cat "$ntmp/d3field.err"; fi
    printf 'type Customer = record id: int, spend: int\nfn q(table: table[Customer]) = query_where(Customer, table, "spend", ">", "four")\n' >"$ntmp/d3type.src"
    "$ntmp/lc" <"$ntmp/d3type.src" >"$ntmp/d3type.s" 2>"$ntmp/d3type.err"; d3type=$?
    if [ "$d3type" = 3 ] && [ ! -s "$ntmp/d3type.s" ] && grep -q "query value for 'spend' has incompatible type" "$ntmp/d3type.err"; then ok "phase-2 D3: query rejects a mismatched comparison type"; else bad "phase-2 D3: query rejects a mismatched comparison type"; cat "$ntmp/d3type.err"; fi
    printf 'type Customer = record id: int, city: str\ntype Order = record customer_id: str\nfn q(a: table[Order], b: table[Customer]) = query_join(Order, Customer, Joined, a, b, "orders", "customers", "customer_id", "id")\ntype Joined = record orders_customer_id: str, customers_id: int, customers_city: str\n' >"$ntmp/d3join.src"
    "$ntmp/lc" <"$ntmp/d3join.src" >"$ntmp/d3join.s" 2>"$ntmp/d3join.err"; d3join=$?
    if [ "$d3join" = 3 ] && [ ! -s "$ntmp/d3join.s" ] && grep -q "query_join key fields have different types" "$ntmp/d3join.err"; then ok "phase-2 D3: join rejects incompatible key types"; else bad "phase-2 D3: join rejects incompatible key types"; cat "$ntmp/d3join.err"; fi
    # phase-2 M1: the AST as a first-class comptime value (`quote`, `match` over AST constructors + string/int patterns, `splice`).
    "$ntmp/lc" <../../compiler/stage1/ast_meta.src >"$ntmp/am.s" 2>/dev/null; "$ntmp/lasm" <"$ntmp/am.s" >"$ntmp/am.elf" 2>/dev/null; chmod +x "$ntmp/am.elf"
    m1_ok=1
    "$ntmp/am.elf" 2>/dev/null | diff -u ../../tests/conformance/stage1/ast_meta_asm.expected - >/dev/null || m1_ok=0
    # PROOF of zero-overhead AST transformation & splicing:
    # 1. `fast_linear(x, y) = splice(simplify(quote(((x + 0) * 1) + ((0 + y) - 0))))` must emit ONLY `x + y` (`call addv`), with NO `imulq`, `subq %rcx`, or `$0` in its body.
    awk '/^fast_linear:/{p=1} p{print} p&&/^    ret$/{exit}' "$ntmp/am.s" >"$ntmp/am_fl.s"
    grep -q 'call addv' "$ntmp/am_fl.s" || m1_ok=0
    grep -Eq 'imulq|subq %rcx|movq \$0,' "$ntmp/am_fl.s" && m1_ok=0
    # 2. `pow4(x) = splice(unroll_pow("x", 4))` must emit inline `imulq` instructions with NO call to `unroll_pow` or recursive `call pow4`.
    awk '/^pow4:/{p=1} p{print} p&&/^    ret$/{exit}' "$ntmp/am.s" >"$ntmp/am_p4.s"
    grep -q 'imulq' "$ntmp/am_p4.s" || m1_ok=0
    grep -Eq 'call unroll_pow|call pow4' "$ntmp/am_p4.s" && m1_ok=0
    # 3. `comptime(ast_nodes(...))` folds to `movq $7, %rdi` in `_start` with NO call to `ast_nodes` or `ast_sexpr`.
    awk '/^_start:/{p=1} p{print}' "$ntmp/am.s" >"$ntmp/am_main.s"
    grep -q 'movq \$7, %rdi' "$ntmp/am_main.s" || m1_ok=0
    grep -Eq 'call ast_nodes|call ast_sexpr' "$ntmp/am_main.s" && m1_ok=0
    if [ "$m1_ok" = 1 ]; then ok "phase-2 M1: first-class comptime AST (quote, match over AST, algebraic simplify & unroll via splice)"; else bad "phase-2 M1: first-class comptime AST (quote, match, splice)"; fi
    printf 'print splice(42)\n' >"$ntmp/m1bad1.src"
    printf 'print splice(Bin("???", Num(1), Num(2)))\n' >"$ntmp/m1bad2.src"
    "$ntmp/lc" <"$ntmp/m1bad1.src" >"$ntmp/m1bad1.s" 2>"$ntmp/m1bad1.err"; m1b1=$?
    "$ntmp/lc" <"$ntmp/m1bad2.src" >"$ntmp/m1bad2.s" 2>"$ntmp/m1bad2.err"; m1b2=$?
    if [ "$m1b1" = 3 ] && [ ! -s "$ntmp/m1bad1.s" ] && grep -q "splice expects an AST constructor" "$ntmp/m1bad1.err" && [ "$m1b2" = 3 ] && [ ! -s "$ntmp/m1bad2.s" ] && grep -q "invalid AST node" "$ntmp/m1bad2.err"; then ok "phase-2 M1: invalid AST splice fails at compile time with a clear error (exit 3, no asm)"; else bad "phase-2 M1: invalid AST splice fails at compile time"; fi
    # phase-2 M2: hygienic macros / quasiquote (`unquote(<expr>)` inside `quote(...)`, lexical variable capture avoidance).
    "$ntmp/lc" <../../compiler/stage1/macro_hygiene.src >"$ntmp/mh.s" 2>/dev/null; "$ntmp/lasm" <"$ntmp/mh.s" >"$ntmp/mh.elf" 2>/dev/null; chmod +x "$ntmp/mh.elf"
    m2_ok=1
    "$ntmp/mh.elf" 2>/dev/null | diff -u ../../tests/conformance/stage1/macro_hygiene_asm.expected - >/dev/null || m2_ok=0
    awk '/^_start:/{p=1} p{print}' "$ntmp/mh.s" >"$ntmp/mh_main.s"
    grep -Eq 'call m_with_tmp|call m_wrap_tmp|call m_let_tmp|call m_linear|call m_if_pos' "$ntmp/mh_main.s" && m2_ok=0
    if [ "$m2_ok" = 1 ]; then ok "phase-2 M2: hygienic macros / quasiquote (unquote interpolation + variable capture avoidance)"; else bad "phase-2 M2: hygienic macros / quasiquote"; fi
    printf 'print unquote(1)\n' >"$ntmp/m2bad1.src"
    printf 'print comptime(quote(unquote(1, 2)))\n' >"$ntmp/m2bad2.src"
    "$ntmp/lc" <"$ntmp/m2bad1.src" >"$ntmp/m2bad1.s" 2>"$ntmp/m2bad1.err"; m2b1=$?
    "$ntmp/lc" <"$ntmp/m2bad2.src" >"$ntmp/m2bad2.s" 2>"$ntmp/m2bad2.err"; m2b2=$?
    if [ "$m2b1" = 3 ] && [ ! -s "$ntmp/m2bad1.s" ] && grep -q "'unquote' may only appear inside 'quote(...)'" "$ntmp/m2bad1.err" && [ "$m2b2" = 3 ] && [ ! -s "$ntmp/m2bad2.s" ] && grep -q "'unquote' expects exactly 1 argument" "$ntmp/m2bad2.err"; then ok "phase-2 M2: unquote outside quote or with wrong arity fails at compile time (exit 3, no asm)"; else bad "phase-2 M2: unquote outside quote or with wrong arity fails at compile time"; fi
    # phase-2 C4: `comptime assert` -- a condition evaluated entirely at compile time that leaves no runtime check.
    "$ntmp/lc" <../../compiler/stage1/comptime_assert.src >"$ntmp/ca.s" 2>"$ntmp/ca.err"; "$ntmp/lasm" <"$ntmp/ca.s" >"$ntmp/ca.elf" 2>/dev/null; chmod +x "$ntmp/ca.elf"
    ca_ok=1
    { [ -x "$ntmp/ca.elf" ] && "$ntmp/ca.elf" 2>/dev/null | diff -u ../../tests/conformance/stage1/comptime_assert_asm.expected - >/dev/null; } || ca_ok=0
    # PROOF the passing asserts ran at compile time: the assert's `sq(5)` is folded away, so the only `call sq`
    # left in the emitted assembly is the one from `print sq(7)`.
    [ "$(grep -c 'call sq' "$ntmp/ca.s")" = 1 ] || ca_ok=0
    if [ "$ca_ok" = 1 ]; then ok "phase-2 C4: comptime assert passes at compile time and leaves no runtime check (sq(5) folded)"; else bad "phase-2 C4: comptime assert (passing)"; cat "$ntmp/ca.err"; fi
    printf 'comptime assert(1 == 2)\nprint 7\n' >"$ntmp/c4bad1.src"
    printf 'comptime assert(3 > 9, "three is not greater than nine")\nprint 7\n' >"$ntmp/c4bad2.src"
    "$ntmp/lc" <"$ntmp/c4bad1.src" >"$ntmp/c4bad1.s" 2>"$ntmp/c4bad1.err"; c4b1=$?
    "$ntmp/lc" <"$ntmp/c4bad2.src" >"$ntmp/c4bad2.s" 2>"$ntmp/c4bad2.err"; c4b2=$?
    if [ "$c4b1" = 3 ] && [ ! -s "$ntmp/c4bad1.s" ] && grep -q "comptime assertion failed" "$ntmp/c4bad1.err" && [ "$c4b2" = 3 ] && [ ! -s "$ntmp/c4bad2.s" ] && grep -q "comptime assertion failed: three is not greater than nine" "$ntmp/c4bad2.err"; then ok "phase-2 C4: a false comptime assert fails the build (exit 3, no asm) with a clear message"; else bad "phase-2 C4: false comptime assert fails at compile time"; fi
    rm -rf "$ntmp"
else
    ok "no-toolchain ELF pipeline (skipped: not linux/x86_64, or under ASan)"
fi

if ../../lume --version | grep -q "^lume " && ../../lume check ../../examples/01_hello.lume >/dev/null 2>&1 && ../../lume test ../../examples/01_hello.lume | grep -q "1 passed, 0 failed"; then ok "phase-2 T1: lume CLI (--version, check, test on surface .lume)"; else bad "phase-2 T1: lume CLI (--version, check, test on surface .lume)"; fi

echo "== AI-first: `lume0 describe` emits valid JSON"
if command -v python3 >/dev/null 2>&1; then
    if $BIN describe | python3 -c 'import json,sys; json.load(sys.stdin)' 2>/dev/null; then ok "describe --json"; else bad "describe --json"; fi
fi

echo "== Lume-in-Lume: Stage-1 programs run under lume0"
for exp in ../../tests/conformance/stage1/*.expected; do
    [ -f "$exp" ] || continue
    base=$(basename "$exp" .expected)
    src="../../compiler/stage1/$base.lume"
    [ -f "$src" ] || continue    # expected files without a matching .lume (e.g. native-binary tests) are handled elsewhere
    if $BIN run "$src" 2>/dev/null | diff -u "$exp" - >/dev/null; then ok "compiler/stage1/$base.lume"; else bad "compiler/stage1/$base.lume"; $BIN run "$src" 2>/dev/null | diff -u "$exp" - | head -20; fi
done

echo "== LBE: emit to binary AST and run it with no re-parse (output must match text run)"
tmpd=$(mktemp -d)
for exp in ../../tests/conformance/stage0/*.expected; do
    [ -f "$exp" ] || continue
    base=$(basename "$exp" .expected)
    src="$EX/$base.lume"
    $BIN emit "$src" "$tmpd/$base.lbe" 2>/dev/null
    if $BIN run "$tmpd/$base.lbe" 2>/dev/null | diff -u "$exp" - >/dev/null; then ok "lbe $base"; else bad "lbe $base"; fi
done
rm -rf "$tmpd"

echo "== negative lexer cases"
for src in tests/lexer/bad_*.lume; do
    code=$(sed -n '1s/^# expect: //p' "$src")
    if $BIN check "$src" --json 2>/dev/null | grep -q "\"code\":\"$code\""; then ok "$src ($code)"; else bad "$src (expected $code)"; fi
done

echo "== negative parser cases"
for src in tests/parser/bad_*.lume; do
    [ -f "$src" ] || continue
    code=$(sed -n '1s/^# expect: //p' "$src")
    if $BIN check "$src" --json 2>/dev/null | grep -q "\"code\":\"$code\""; then ok "$src ($code)"; else bad "$src (expected $code)"; $BIN check "$src" --json; fi
done

echo "== resolve: undefined names are caught at check time"
for src in tests/resolve/bad_*.lume; do
    [ -f "$src" ] || continue
    code=$(sed -n '1s/^# expect: //p' "$src")
    if $BIN check "$src" --json 2>/dev/null | grep -q "\"code\":\"$code\""; then ok "$src ($code)"; else bad "$src (expected $code)"; $BIN check "$src" --json; fi
done
for src in tests/resolve/ok_*.lume; do
    [ -f "$src" ] || continue
    if $BIN check "$src" >/dev/null 2>e.txt; then ok "$src (clean)"; else bad "$src (should resolve clean)"; sed 's/^/      /' e.txt | head -4; fi
done

echo "== positive parser cases (must parse clean)"
for src in tests/parser/ok_*.lume; do
    [ -f "$src" ] || continue
    # parser ok-tests assert PARSING only (bare free identifiers are expected); use parse, not check
    if $BIN parse "$src" >/dev/null 2>e.txt; then ok "$src"; else bad "$src"; sed 's/^/      /' e.txt | head -4; fi
done

rm -f e.txt
echo "$pass passed, $fail failed"
[ "$fail" -eq 0 ]
